function buildHezarFlatList() {
  const out = [];
  HEZAR_SUBLISTS.forEach(function(sub) {
    sub.episodes.forEach(function(e) {
      out.push({
        mode: 'hekayat',
        collectionId: 'hezar',
        collection: 'هزار و یک شب',
        subCollection: sub.label,
        author: sub.author,
        title: e.title,
        subtitle: sub.label + ' — ' + e.title,
        info: sub.info,
        duration: e.duration || '',
        src: e.src,
        url: sub.url,
        pubDate: e.pubDate || ''
      });
    });
  });
  return out;
}
